const j = $input.first().json;
const ex = j.execution || {};
const err = ex.error || {};
const wf = j.workflow || {};
let msg = err.message || String(err) || 'unknown error';
// The runner returns {"ok":false,"stage":..,"error":..,"fix":..}; n8n often embeds that JSON in the message. Try to pull it out.
let stage = ex.lastNodeExecuted || '?';
let fix = null;
let jobHint = null;
const m = msg.match(/\{[\s\S]*"ok"\s*:\s*false[\s\S]*\}/);
if (m) {
  try {
    const body = JSON.parse(m[0]);
    if (body.stage) stage = `${ex.lastNodeExecuted || '?'} (${body.stage})`;
    if (body.error) msg = body.error;
    if (body.fix) fix = body.fix;
  } catch (e) { /* keep raw message */ }
}
const jm = msg.match(/[A-Za-z0-9_-]+_\d{8}_\d{6}/);
if (jm) jobHint = jm[0];
const fm = msg.match(/[A-Za-z]:\\[^"'\n]+\.(mp4|mkv|mov|webm)/i);
const fileHint = fm ? fm[0] : null;

const lines = [
  `❌ Personal Clipper failed`,
  `Workflow: ${wf.name || '?'}`,
  `Stage / node: ${stage}`,
];
if (fileHint) lines.push(`Input: ${fileHint}`);
if (jobHint) lines.push(`Job: ${jobHint}`);
lines.push(`Error: ${msg}`);
if (fix) lines.push(`Fix: ${fix}`);
if (ex.url) lines.push(`Execution: ${ex.url}`);
return [{ json: { text: lines.join('\n'), chat_id: j.TELEGRAM_CHAT_ID } }];
